                    html += `<div class="hq-chips"><span>THE THREE FORMS · ONE IS CURRENT · THE OTHERS NEVER WERE</span>${bar.forms.map((f, i) => `<i class="hq-chip ${i === bar.idx ? '' : 'dim'}">${_hqEsc(f)}</i>`).join('')}</div>`;
                    html += '<div class="hq-rows">'
