                    bar.remembered.forEach(r => { html += `<div class="hq-row hq-row-tray"><b>YOU REMEMBER</b><span>UNTIL ${_hqEsc(r.until || '—')} · NOBODY ELSE DOES</span><i class="hq-lamp-chip st-off">${_hqEsc(r.text)}</i></div>`; });
