                    if (!inEllipse(tx, ty, outerRx, outerRy)) continue;

                    const isEarth = inEllipse(tx, ty, earthRx, earthRy);
                    const inBorderInner = inEllipse(tx, ty, borderInnerRx, borderInnerRy);
